enum ENUM_STOP_MODE
{
   STOP_SIGNAL_BAR    = 0, // Mínima/Máxima da Barra de Sinal (+ Buffer)
   STOP_POC_LEVEL     = 1, // Nível do POC da Barra / Zona (+ Buffer)
   STOP_FIXED_POINTS  = 2  // Pontos Fixos
};

enum ENUM_TP_MODE
{
   TP_RISK_REWARD     = 0, // Baseado em Risco:Retorno (Ex: 1:1.5 ou 1:2.0)
   TP_FIXED_POINTS    = 1  // Pontos Fixos
};

enum ENUM_LOT_MODE
{
   LOT_FIXED          = 0, // Lote Fixo
   LOT_RISK_PERCENT   = 1  // Percentual de Risco sobre o Balanço
};

enum ENUM_POC_MIGRATION_STATE
{
   MIGRATION_NONE        = 0,
   MIGRATION_UP          = 1, // ALTA (POCs subindo com preços)
   MIGRATION_DOWN        = 2, // BAIXA (POCs descendo com preços)
   MIGRATION_CONSOLIDATED = 3 // LATERAL / CONSOLIDAÇÃO (POCs agrupados)
};

